/* Stable asset identities survive directory moves and shared-file deduplication. */
(()=>{
 'use strict';
 const index=window.CatRulerIndex,root=new URL('../../',document.currentScript.src).href;
 const url=path=>new URL(path,root).href;
 const reverse=new Map();
 for(const [key,path] of Object.entries(index.files))if(!key.startsWith('@'))reverse.set(url(path),key);
 const has=key=>Object.hasOwn(index.files,key);
 function asset(key){
  key=String(key||'');if(!key)return root;
  if(/^(https?:|file:)/.test(key))return key;
  const hash=key.indexOf('#'),suffix=hash<0?'':key.slice(hash),name=hash<0?key:key.slice(0,hash);
  return url(index.files[name]||('_missing/'+name))+suffix;
 }
 const contains=raw=>!!raw&&(raw.startsWith(root)||reverse.has(raw.split('#')[0]));
 function data(name,packed){const path=(packed?index.packed:index.datasets)[name];if(!path)throw Error('这部分资料尚未收录。');return url(path);}
 window.CatRulerRelease={root,url,asset,has,contains,data,key:raw=>reverse.get(raw.split('#')[0])||raw,play:name=>url(index.playable[name])};
 document.addEventListener('DOMContentLoaded',()=>{if(new URL(location.href).searchParams.get('open')==='works')window.HerArchive?.open('works','all');},{once:true});
})();
